#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long k;
    scanf("%d %lld", &n, &k);
    vector<int> a(n);
    for (auto& x : a) scanf("%d", &x);
    unordered_map<int, int> freq;
    freq.reserve(2 * n + 1);
    long long pairs = 0, answer = 0;
    int left = 0;
    for (int right = 0; right < n; right++) {
        // Disjoint pairs in the window = sum of floor(count / 2) over values.
        if (freq[a[right]]++ % 2) pairs++;
        while (pairs >= k) {
            if (freq[a[left]]-- % 2 == 0) pairs--;
            left++;
        }
        answer += left;  // every start in [0, left) keeps at least k pairs
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        boolean neg = buf[bp] == '-';
        if (neg) bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long k = nextLong();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = (int) nextLong();
        // Compress values to ids so frequencies live in an int array.
        int[] sorted = a.clone();
        Arrays.sort(sorted);
        int[] id = new int[n];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(sorted, a[i]);
        int[] freq = new int[n];
        long pairs = 0, answer = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            // Disjoint pairs in the window = sum of floor(count / 2) over values.
            if (freq[id[right]]++ % 2 == 1) pairs++;
            while (pairs >= k) {
                if (freq[id[left]]-- % 2 == 0) pairs--;
                left++;
            }
            answer += left;  // every start in [0, left) keeps at least k pairs
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n, k := int(next()), next()
	a := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	freq := make(map[int64]int, n)
	var pairs, answer int64
	left := 0
	for right := 0; right < n; right++ {
		// Disjoint pairs in the window = sum of floor(count / 2) over values.
		if freq[a[right]]%2 == 1 {
			pairs++
		}
		freq[a[right]]++
		for pairs >= k {
			if freq[a[left]]%2 == 0 {
				pairs--
			}
			freq[a[left]]--
			left++
		}
		answer += int64(left) // every start in [0, left) keeps at least k pairs
	}
	fmt.Println(answer)
}
